// Payment robot ("the bank") — see specs/shared/n8n-workflows.md §4.
// Pays every invoice issued at least PAYMENT_AGE_MINUTES ago, using a
// deterministic paymentReference so a replay is a safe no-op (R48).

const gatewayUrl = ($env.OTC_GATEWAY_URL || 'http://gateway:3001').replace(/\/$/, '');
const username = $env.GATEWAY_OPERATOR_USERNAME;
const password = $env.GATEWAY_OPERATOR_PASSWORD;
const timeoutMs = Number($env.OTC_REQUEST_TIMEOUT_MS || 10000);

const enabled = ($env.PAYMENT_ROBOT_ENABLED ?? 'true') !== 'false';
const ageMinutes = Number($env.PAYMENT_AGE_MINUTES ?? 2);
const batchSize = Number($env.PAYMENT_ROBOT_BATCH_SIZE || 10);
const retailerFilter = ($env.PAYMENT_ROBOT_RETAILERS || '').split(',').map((s) => s.trim()).filter(Boolean);

if (!enabled) {
  return [{ json: { skipped: true, reason: 'PAYMENT_ROBOT_ENABLED=false' } }];
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function requestWithRetry(options, { retryOn5xxAndNetwork = true } = {}) {
  const attempts = retryOn5xxAndNetwork ? 4 : 1;
  let lastErr;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await this.helpers.httpRequest({ timeout: timeoutMs, ...options });
    } catch (err) {
      lastErr = err;
      const status = err.status ?? err.response?.status;
      const isNetworkError = status === undefined;
      const is5xx = typeof status === 'number' && status >= 500;
      if (!retryOn5xxAndNetwork || !(isNetworkError || is5xx) || attempt === attempts - 1) {
        throw err;
      }
      await sleep(2 ** attempt * 250);
    }
  }
  throw lastErr;
}

async function login() {
  const res = await requestWithRetry.call(this, {
    method: 'POST',
    url: `${gatewayUrl}/auth/login`,
    body: { username, password },
    json: true,
  });
  return res.accessToken;
}

function authHeaders(token) {
  return { Authorization: `Bearer ${token}` };
}

async function listDueInvoices(token) {
  const qs = {
    status: 'issued',
    issuedBeforeMinutes: ageMinutes,
    pageSize: batchSize,
  };
  const res = await requestWithRetry.call(this, {
    method: 'GET', url: `${gatewayUrl}/invoices`, headers: authHeaders(token), qs, json: true,
  });
  let items = res.items;
  if (retailerFilter.length) {
    items = items.filter((inv) => retailerFilter.includes(inv.retailerCode));
  }
  return items;
}

async function payInvoice(token, invoice) {
  const paymentReference = `PAY-${invoice.invoiceReference}`;
  const body = {
    paymentReference,
    amount: { amount: invoice.totalAmount, currency: invoice.currency },
    valueDate: new Date().toISOString(),
    source: 'robot',
  };
  try {
    const res = await requestWithRetry.call(this, {
      method: 'POST',
      url: `${gatewayUrl}/invoices/${invoice.invoiceId}/payments`,
      headers: authHeaders(token),
      body,
      json: true,
      returnFullResponse: true,
    });
    return {
      outcome: res.statusCode === 201 ? 'paid' : 'duplicate',
      status: res.statusCode,
      invoiceReference: invoice.invoiceReference,
      orderReference: invoice.orderReference,
      paymentReference,
    };
  } catch (err) {
    const status = err.status ?? err.response?.status;
    if (status === 409 || status === 422) {
      return { outcome: 'skipped', status, invoiceReference: invoice.invoiceReference, orderReference: invoice.orderReference, paymentReference };
    }
    if (status === 401) {
      const freshToken = await login.call(this);
      const res = await this.helpers.httpRequest({
        method: 'POST', url: `${gatewayUrl}/invoices/${invoice.invoiceId}/payments`,
        headers: authHeaders(freshToken), body, json: true, timeout: timeoutMs, returnFullResponse: true,
      });
      return { outcome: res.statusCode === 201 ? 'paid' : 'duplicate', status: res.statusCode, invoiceReference: invoice.invoiceReference, orderReference: invoice.orderReference, paymentReference };
    }
    throw err;
  }
}

async function run() {
  const token = await login.call(this);
  const invoices = await listDueInvoices.call(this, token);
  const results = [];
  for (const invoice of invoices) {
    try {
      results.push(await payInvoice.call(this, token, invoice));
    } catch (err) {
      results.push({ outcome: 'error', invoiceReference: invoice.invoiceReference, message: err.message, status: err.status ?? err.response?.status });
    }
  }
  return results;
}

const runResults = await run.call(this);
if (runResults.length === 0) return [{ json: { paid: 0, duplicate: 0, skipped: 0, message: 'no invoices due' } }];
return runResults.map((r) => ({ json: r }));
